<?php
$me=user();$title='Dashboard';$subtitle=date('l, d F Y');$S=scope();$pro=mod('prospecting')&&can('prospecting');
$c=DB::row("SELECT COUNT(*) t,SUM(l.created_at>=CURDATE()) td,SUM(l.created_at>=NOW()-INTERVAL 7 DAY) wk,SUM(l.status='new') nw,SUM(l.status='won') wn,SUM(CASE WHEN l.status='won' THEN l.deal_value ELSE 0 END) wv,SUM(CASE WHEN l.status NOT IN ('won','lost') THEN l.deal_value ELSE 0 END) pv,SUM(l.follow_up_at IS NOT NULL AND l.follow_up_at<=NOW() AND l.status NOT IN ('won','lost')) due FROM leads l WHERE l.is_lead=1$S");
$st=[];foreach(DB::all("SELECT l.status,COUNT(*) n FROM leads l WHERE l.is_lead=1$S GROUP BY l.status") as $r)$st[$r['status']]=(int)$r['n'];
$srcs=DB::all("SELECT l.source,COUNT(*) n FROM leads l WHERE l.is_lead=1$S GROUP BY l.source ORDER BY n DESC");
$au=role()==='sales'?' AND (a.user_id='.(int)$me['id'].' OR l.assigned_to='.(int)$me['id'].' OR l.assigned_to IS NULL)':'';
$appts=DB::all("SELECT a.*,l.name,l.contact_name FROM appointments a LEFT JOIN leads l ON l.id=a.lead_id WHERE a.status='scheduled' AND a.start_at>=NOW()-INTERVAL 1 HOUR$au ORDER BY a.start_at LIMIT 5");
$up=(int)DB::val("SELECT COUNT(*) FROM appointments a LEFT JOIN leads l ON l.id=a.lead_id WHERE a.status='scheduled' AND a.start_at>=NOW()$au");
$fu=DB::all("SELECT l.id,l.name,l.contact_name,l.follow_up_at,l.phone FROM leads l WHERE l.is_lead=1 AND l.follow_up_at IS NOT NULL AND l.follow_up_at<=NOW()+INTERVAL 1 DAY AND l.status NOT IN ('won','lost')$S ORDER BY l.follow_up_at LIMIT 6");
$ev=DB::all("SELECT e.*,l.name,l.contact_name FROM events e JOIN leads l ON l.id=e.lead_id WHERE 1=1".($pro?'':' AND l.is_lead=1').$S." ORDER BY e.id DESC LIMIT 8");
if($pro){$p=array_map('intval',DB::row("SELECT SUM(source='maps') t,SUM(source='maps' AND map_score IS NOT NULL) au,SUM(source='maps' AND stage IN ('report_ready','contacting','contacted','opened','replied','won','lost')) rr,SUM(source='maps' AND (email_status IN ('sent','opened') OR wa_status IN ('sent','delivered','read','manual'))) ct,SUM(source='maps' AND (email_status='opened' OR wa_status='read' OR stage='opened')) op,SUM(source='maps' AND replied_at IS NOT NULL) rp,SUM(source='maps' AND is_lead=1) il,SUM(stage IN ('queued','auditing','reporting','contacting')) wk FROM leads"));}
$checks=[];
if(can('settings')){
  $ai=setting('ai_key_'.setting('ai_provider','anthropic'))!=='';$maps=setting('maps_source')==='serpapi'?setting('serpapi_key')!=='':setting('google_api_key')!=='';
  $checks=[[Mailer::ready(),'Check email sending','settings&tab=email'],[setting('wa_provider')!=='manual','Connect WhatsApp API (optional)','settings&tab=whatsapp'],[(bool)DB::val('SELECT COUNT(*) FROM sources'),'Capture leads from forms & ads','settings&tab=capture'],[(bool)DB::val('SELECT COUNT(*) FROM automations WHERE active=1'),'Switch on an automation','automations'],[GCal::ready(),'Sync Google Calendar (optional)','settings&tab=appointments'],[(int)DB::val('SELECT COUNT(*) FROM users')>1,'Invite your team','team']];
  if($pro)array_unshift($checks,[$ai,'Connect an AI provider','ai'],[$maps,'Add a Google Maps API key','settings&tab=data']);}
$done=count(array_filter(array_column($checks,0)));
$evc=['found'=>'pin','enriched'=>'globe','audited'=>'activity','stage'=>'zap','sent'=>'send','opened'=>'eye','viewed'=>'eye','replied'=>'msg','error'=>'alert','note'=>'edit','scheduled'=>'clock','wa_manual'=>'wa','call'=>'mic','auto'=>'bot','booked'=>'cal'];
$cc=['blue'=>'blue','teal'=>'teal','purple'=>'violet','orange'=>'orange','gold'=>'amber','green'=>'green','red'=>'rose'];
$h=(int)date('G');$hi=$h<12?'Good morning':($h<17?'Good afternoon':'Good evening');
$fu=array_slice($fu,0,4);$agenda=count($appts)+count($fu);
?>
<div class="ph"><div><h2 style="font-size:20px"><?=$hi?>, <?=e(explode(' ',$me['name'])[0])?> 👋</h2><p class="muted sm mb0"><?=(int)$c['due']?'<b class="red">'.(int)$c['due'].' follow-up'.((int)$c['due']>1?'s':'').' due</b>':'No follow-ups due'?><?=$appts?' · next meeting '.e(date('D h:i A',strtotime($appts[0]['start_at']))):''?></p></div><div class="pha"><a class="btn btn-sm" href="<?=url('appointments',['add'=>1])?>"><?=icon('cal')?>Book meeting</a><?php if($pro):?><a class="btn btn-sm" href="<?=url('scraper',['new'=>1])?>"><?=icon('map')?>Map search</a><?php endif?><a class="btn btn-sm btn-p" href="<?=url('lead_new')?>"><?=icon('plus')?>Add lead</a></div></div>
<div class="stats"><?=kpi('Follow-ups due',(int)$c['due'],'clock','orange',$c['due']?'<span class="dn">act today</span>':'all caught up',url('leads',['fu'=>'due']))?><?=kpi('New – need first touch',(int)$c['nw'],'zap','sky','waiting for a call or message',url('leads',['status'=>'new']))?><?=kpi('Upcoming meetings',$up,'cal','teal',$appts?'next '.date('d M, h:i A',strtotime($appts[0]['start_at'])):'none booked',url('appointments'))?><?=kpi(role()==='sales'?'My leads':'Total leads',number_format((int)$c['t']),'users','indigo','<span class="up">+'.(int)$c['wk'].'</span> this week · '.(int)$c['td'].' today',url('leads'))?><?=kpi('Won',money($c['wv']),'target','green',(int)$c['wn'].' deals · '.money($c['pv']).' open',url('leads',['status'=>'won']))?></div>
<div class="g2 compact"><div class="card"><div class="card-h"><h3><span class="hi c-teal"><?=icon('cal')?></span>Today &amp; next</h3><a class="lnk sm" href="<?=url('appointments')?>">Calendar</a></div><?php if(!$agenda):?><div class="empty sm"><?=icon('cal')?><p>Nothing in the next 24 hours.</p></div><?php endif?><?php foreach(array_slice($appts,0,3) as $a):?><div class="li"><span class="when c-teal"><b><?=date('d',strtotime($a['start_at']))?></b><small><?=date('M',strtotime($a['start_at']))?></small></span><div class="grow"><b><a href="<?=url('lead',['id'=>$a['lead_id']])?>"><?=e($a['contact_name']?:$a['name'])?></a></b><small><?=e(date('D h:i A',strtotime($a['start_at'])))?> · <?=e($a['title'])?></small></div><?php if($a['meet_link']):?><a class="btn btn-xs btn-g" href="<?=e($a['meet_link'])?>" target="_blank" rel="noopener">Join</a><?php else:?><span class="bdg c-teal">Meeting</span><?php endif?></div><?php endforeach?><?php foreach($fu as $f):$late=strtotime($f['follow_up_at'])<=time();?><div class="li"><span class="when <?=$late?'c-rose':'c-orange'?>"><b><?=date('d',strtotime($f['follow_up_at']))?></b><small><?=date('M',strtotime($f['follow_up_at']))?></small></span><div class="grow"><b><a href="<?=url('lead',['id'=>$f['id']])?>"><?=e($f['contact_name']?:$f['name'])?></a></b><small><?=e(date('h:i A',strtotime($f['follow_up_at'])))?><?=$f['phone']?' · '.e($f['phone']):''?></small></div><?php if($f['phone']):?><a class="ib bd" href="tel:<?=e(preg_replace('/[^\d+]/','',$f['phone']))?>" title="Call"><?=icon('phone')?></a><?php endif?><span class="bdg <?=$late?'c-rose':'c-orange'?>"><?=$late?'Overdue':'Due'?></span></div><?php endforeach?><?php if($c['due']>count($fu)):?><div class="vm"><a href="<?=url('leads',['fu'=>'due'])?>">View all <?=(int)$c['due']?> follow-ups →</a></div><?php endif?></div>
<div class="card"><div class="card-h"><h3><span class="hi c-green"><?=icon('kanban')?></span>Pipeline</h3><a class="lnk sm" href="<?=url('leads')?>">All leads</a></div><div class="bars"><?php $mx=max(1,max($st?:[0]));foreach(crm_statuses() as $k=>[$lb,$cl]):$n=$st[$k]??0;?><a class="bar c-<?=$cc[$cl]?>" href="<?=url('leads',['status'=>$k])?>"><span><?=e($lb)?></span><div><i style="width:<?=max(2,round($n/$mx*100))?>%"></i></div><b><?=$n?></b></a><?php endforeach?></div></div></div>
<div class="g2 compact"><div class="card"><div class="card-h"><h3><span class="hi c-violet"><?=icon('activity')?></span>Recent activity</h3></div><?php if(!$ev):?><div class="empty sm"><?=icon('activity')?><p>No activity yet. Add a lead to get started.</p></div><?php else:?><ul class="tl" style="margin-top:0"><?php foreach(array_slice($ev,0,6) as $x):?><li class="ev-<?=e($x['type'])?>"><i><?=icon($evc[$x['type']]??'zap')?></i><div><span><a href="<?=url('lead',['id'=>$x['lead_id']])?>"><b><?=e($x['contact_name']?:$x['name'])?></b></a> · <?=e(mb_strimwidth($x['message'],0,90,'…'))?></span><small><?=ago($x['created_at'])?></small></div></li><?php endforeach?></ul><div class="vm"><a href="<?=url('activity')?>">View all activity →</a></div><?php endif?></div>
<div class="col"><?php if($pro):$fun=[['Scraped',$p['t'],'gray'],['Audited',$p['au'],'sky'],['Report ready',$p['rr'],'violet'],['Contacted',$p['ct'],'amber'],['Replied',$p['rp'],'green'],['Moved to Leads',$p['il'],'pink']];$max=max(1,$p['t']);?><div class="card"><div class="card-h"><h3><span class="hi c-orange"><?=icon('map')?></span>Prospecting</h3><a class="lnk sm" href="<?=url('prospects')?>">Scraped data</a></div><div class="bars"><?php foreach($fun as [$lb,$n,$cl]):?><div class="bar c-<?=$cl?>"><span><?=e($lb)?></span><div><i style="width:<?=max(2,round($n/$max*100))?>%"></i></div><b><?=$n?></b></div><?php endforeach?></div><?php if($p['wk']):?><p class="hint"><span class="spin"></span> <?=$p['wk']?> processing now</p><?php endif?></div><?php endif?>
<?php if($srcs):?><div class="card"><div class="card-h"><h3><span class="hi c-pink"><?=icon('plug')?></span>Lead sources</h3></div><div class="chips mb0"><?php foreach($srcs as $s):[$lb,$cl,$ic]=lead_sources()[$s['source']]??[ucfirst($s['source']),'gray','link'];?><a href="<?=url('leads',['src'=>$s['source']])?>" class="src-<?=$cl?>"><?=icon($ic)?><?=e($lb)?> <em><?=$s['n']?></em></a><?php endforeach?></div></div><?php endif?></div></div>
<?php if($checks&&$done<count($checks)):?><div class="card compact"><div class="card-h"><h3><span class="hi c-amber"><?=icon('zap')?></span>Finish setting up</h3><span class="bdg c-amber"><?=$done?> of <?=count($checks)?> done</span></div><div class="steps"><?php foreach($checks as [$ok,$lb,$u]):if($ok)continue;?><a href="index.php?r=<?=$u?>" class="step"><?=icon('clock')?><span><?=e($lb)?></span></a><?php endforeach?></div></div><?php endif?>
